insert into public.company_data_documents(kind, document_id, owner_id, payload)
select 'cv_profile', p.id::text, p.id,
  row.payload || jsonb_build_object('languages','', 'portfolio','', 'location','', 'revisions','[]'::jsonb, 'templateSource','CV Template_ver3.pdf')
from public.profiles p join template_rows row on row.employee_code = p.employee_code
where p.status = 'active'
on conflict (kind, document_id) do nothing;
